(()=>{'use strict';let context,bank,bankPromise,active=[],timer,playing=null,generation=0;
const noteNames={piano:'acoustic_grand_piano',guitar:'acoustic_guitar_nylon',violin:'violin',wind:'flute',voice:'choir_aahs',beat:'taiko_drum',electronic:'synth_bass_1',bass:'electric_bass_finger'};
const melody=[0,2,3,7,5,3,2,0],major=[0,4,7,12,11,7,4,0];
const examples={iran:{label:'ملودی نمونه با فلوت',instrument:'wind',notes:melody},classic:{label:'نمونه پیانو با الگوی آرپژ',instrument:'piano',notes:major},pop:{label:'نمونه همراهی ترانه با گیتار',instrument:'guitar',notes:[0,7,12,4,5,12,9,5],chords:true},rhythm:{label:'الگوی کوبه‌ای نمونه',instrument:'beat',notes:[-12,0,-12,7,0,-12,0,7]},electronic:{label:'الگوی الکترونیک نمونه',instrument:'electronic',notes:[-12,-12,0,-5,-12,0,-7,-5]},pluck:{label:'صدای نمونه گیتار نایلون',instrument:'guitar',notes:major},bow:{label:'صدای نمونه ویولن',instrument:'violin',notes:[0,2,4,7,5,4,2,0],slow:true},keys:{label:'صدای نمونه پیانو',instrument:'piano',notes:major},wind:{label:'صدای نمونه فلوت',instrument:'wind',notes:melody,slow:true},beat:{label:'صدای کوبه‌ای نمونه',instrument:'beat',notes:[0,7,0,0,7,0,7,0]},voice:{label:'آوای گروهی سمپل‌شده',instrument:'voice',notes:[0,4,7,5,4,2,0,0],slow:true},digital:{label:'الگوی الکترونیک نمونه',instrument:'electronic',notes:[0,0,7,12,0,7,3,7]},open:{label:'مقایسه چند جنس صدا',medley:true}};
const aliases={sound:{unsure:'open'},style:{open:'open'},touch:{strings:'pluck',bow:'bow',keys:'keys',breath:'wind',hands:'beat',digital:'digital',open:'open'},goal:{accompany:'pop',melody:'bow',ensemble:'classic',rhythm:'rhythm',compose:'keys',sing:'voice',explore:'open'}};
function example(q,value){if(!['style','sound','touch','goal'].includes(q))return null;return examples[aliases[q]?.[value]||value]||null}
function reset(button){if(!button)return;button.classList.remove('is-playing');button.setAttribute('aria-pressed','false');button.textContent='▶ بشنو';button.disabled=false}
function stop(){generation++;clearTimeout(timer);active.forEach(n=>{try{n.stop()}catch{}});active=[];reset(playing);playing=null}
async function ready(){context=context||new (window.AudioContext||window.webkitAudioContext)();await context.resume();if(!bankPromise)bankPromise=fetch('audio/guide-bank.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(async data=>{const buffers={};await Promise.all(Object.entries(data).map(async([name,url])=>{const bytes=Uint8Array.from(atob(url.split(',')[1]),c=>c.charCodeAt(0));buffers[name]=await context.decodeAudioData(bytes.buffer)}));bank=buffers}).catch(e=>{bankPromise=null;throw e});await bankPromise;}
function playNote(instrument,semitone,start,duration,volume=.22){const source=context.createBufferSource(),gain=context.createGain();source.buffer=bank[noteNames[instrument]];source.playbackRate.value=2**(semitone/12);gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(volume,start+.015);gain.gain.setValueAtTime(volume,start+Math.max(.02,duration-.09));gain.gain.linearRampToValueAtTime(0,start+duration);source.connect(gain);gain.connect(context.destination);source.start(start);source.stop(start+duration+.02);active.push(source)}
async function play(button,q,value){if(playing===button){stop();return}stop();const run=generation,ex=example(q,value);playing=button;button.textContent='در حال آماده‌سازی…';button.disabled=true;try{await ready();if(run!==generation)return;button.disabled=false;button.classList.add('is-playing');button.textContent='■ توقف';button.setAttribute('aria-pressed','true');const status=document.getElementById('guide-audio-status');if(status)status.textContent=ex.label+'؛ برای توقف دوباره دکمه را بزن.';let duration;if(ex.medley){['guitar','piano','violin','wind'].forEach((i,n)=>{playNote(i,0,context.currentTime+.08+n*1.1,.85);playNote(i,7,context.currentTime+.5+n*1.1,.5)});duration=4.9}else{const interval=ex.slow?.5:.34;ex.notes.forEach((note,i)=>{const start=context.currentTime+.08+i*interval;playNote(ex.instrument,note,start,interval*.92,ex.instrument==='beat'?.32:.21);if(ex.chords&&i%4===0){playNote('guitar',note+4,start+.03,.8,.09);playNote('guitar',note+7,start+.06,.8,.09)}});duration=ex.notes.length*interval+.2}timer=setTimeout(()=>{if(run===generation){stop();if(status)status.textContent='پایان نمونه؛ می‌توانی دوباره بشنوی یا گزینه را انتخاب کنی.'}},duration*1000)}catch{if(run===generation){stop();const status=document.getElementById('guide-audio-status');if(status)status.textContent='پخش صدا انجام نشد؛ اتصال و صدای دستگاه را بررسی کن و دوباره بزن.'}}}
window.HezaravaAudio={stop,available:(q,v)=>!!example(q,v),label:(q,v)=>example(q,v)?.label,bind:(root,q)=>root.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>play(b,q,b.dataset.preview))};document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});})();
